def IsPeriodicField (F : ℝ → Space → Space) : Prop :=
  AEStronglyMeasurable (fun z : ℝ × Space => F z.1 z.2) volume ∧ IsTimePeriodic F ∧
    periodLIntegral (fun σ y => ‖F σ y‖ ^ 2) < ⊤

theorem isExtendedCertificate_of_clause {d : ExtendedCertificateData k} (hd : IsExtendedCertificate d)
    (hc : ExtendedCoerciveClause d) : IsExtendedCertificate d :=
  { hd with coercive := hc }

def IsGradientPair (v : Space → Space) (G : Space → (Space →L[ℝ] Space)) : Prop :=
  AEStronglyMeasurable v volume ∧ MemLp v 6 volume ∧ AEStronglyMeasurable G volume ∧
    Integrable (fun y => entrySq (G y)) ∧ IsWeakGradientOf v G

def radialStripTrace (c o : ℝ) (F dF : ℝ × ℝ → ℂ) (z : ℝ) : ℂ :=
  edgeSign c o * ∫ r in Set.Icc (min c o) (max c o),
    ((((1 / (c - o) : ℝ)) : ℂ) * F (r, z) + (((r - o) / (c - o) : ℝ) : ℂ) * dF (r, z))

def radialFaceMoment (K : CellBox) (F dF : ℝ × ℝ → ℂ) (e : Fin 2) (t : ℝ → ℝ) : ℂ :=
  if e = 1 then radialStripMoment K.r₂ K.r₁ K.z₁ K.z₂ F dF t
  else radialStripMoment K.r₁ K.r₂ K.z₁ K.z₂ F dF t

